NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Malachi'

CHAPTERS = {
    1: {
        1: 'Weissagung. Wort Jehovahs an Israel durch die Hand Maleachis.',
        2: 'Ich habe euch geliebt, spricht Jehovah; und ihr sprecht: Worin hast Du uns geliebt? Ist Esau nicht Jakobs Bruder? spricht Jehovah. Und Jakob liebte Ich.',
        3: 'Und Esau haßte Ich und machte seine Berge zur Verwüstung und sein Erbe den Drachen der Wüste.',
        4: 'So Edom spricht: Wir sind zerschlagen, aber wir kehren zurück und bauen die Verödungen, spricht Jehovah der Heerscharen also: Sie bauen, und Ich reiße ein, und man wird sie die Grenze der Ungerechtigkeit nennen und das Volk, gegen das Jehovah ergrimmt ist ewiglich.',
        5: 'Und eure Augen sollen es sehen, und ihr sollt sprechen: Groß ist Jehovah, über die Grenze Israels hinaus.',
        6: 'Ein Sohn ehrt den Vater und seinen Herrn der Knecht. Bin Ich aber Vater, wo ist Meine Herrlichkeit? Und bin Ich Herr, wo ist die Furcht vor Mir, spricht Jehovah der Heerscharen zu euch, ihr Priester, die ihr verachtet Meinen Namen. Und ihr sprecht: Worin verachten wir Deinen Namen?',
        7: 'Ihr bringt beflecktes Brot herzu auf Meinen Altar und sprecht: Womit beflecken wir Dich? Damit, daß ihr sagt: Der Tisch Jehovahs, er ist verächtlich.',
        8: 'Und wenn ihr herzubringt Blindes zum Opfer, ist das nicht böse? Und wenn ihr herzubringt Lahmes und Krankes, ist das nicht böse? Bringe es doch deinem Statthalter dar, ob er wohl Gefallen an dir hat? Ob er dein Angesicht erhebt? spricht Jehovah der Heerscharen.',
        9: 'Und nun, fleht doch zu Gottes Angesicht, daß Er uns gnädig sei. Von eurer Hand ist solches geschehen, erhebt Er wohl euer Angesicht? spricht Jehovah der Heerscharen.',
        10: 'Wäre doch einer unter euch, der die Torflügel gar zuschlösse, daß ihr nicht umsonst Meinen Altar anzündet. Ich habe an euch keine Lust, spricht Jehovah der Heerscharen, und ein Speiseopfer aus eurer Hand ist Mir nicht wohlgefällig.',
        11: 'Denn vom Aufgang der Sonne und bis zu ihrem Niedergang ist groß Mein Name unter den Völkerschaften, und an jedem Ort wird Meinem Namen Räucherwerk dargebracht und reines Speiseopfer; denn groß ist Mein Name unter den Völkerschaften, spricht Jehovah der Heerscharen.',
        12: 'Ihr aber entweiht ihn, wenn ihr sprecht: Der Tisch Jehovahs, der ist befleckt, und sein Gewächs, seine Speise ist verächtlich.',
        13: 'Und ihr sprecht: Siehe, welche Mühsal, und achtet es gering, spricht Jehovah der Heerscharen, und ihr habt Entrissenes und Lahmes und Krankes hereingebracht, und es als Speiseopfer hereingebracht. Und Ich soll Wohlgefallen daran haben aus eurer Hand? spricht Jehovah.',
        14: 'Darum verflucht sei, wer da trüglich handelt und in seiner Herde hat ein Männliches, und dem Herrn gelobt und opfert ein Verdorbenes; denn ein großer König bin Ich, spricht Jehovah der Heerscharen, und Mein Name ist furchtbar unter den Völkerschaften.',
    },
    2: {
        1: 'Und nun an euch, ihr Priester, ist dies Gebot:',
        2: 'Wenn ihr nicht hört und nicht zu Herzen nehmt, daß ihr Meinem Namen Herrlichkeit gebt, spricht Jehovah der Heerscharen, so sende Ich wider euch die Verwünschung, und verfluche eure Segnungen, und Ich habe sie auch verflucht, weil ihr es nicht zu Herzen nehmt.',
        3: 'Seht, Ich bedrohe wider euch den Samen und sprenge Unrat über eure Angesichter, denn Unrat eurer Feste, und man wird euch zu denselben wegnehmen.',
        4: 'Und ihr werdet erkennen, daß Ich solches Gebot an euch gesandt, auf daß Mein Bund mit Levi sein sollte, spricht Jehovah der Heerscharen.',
        5: 'Mein Bund war mit ihm, der des Lebens und des Friedens, und Ich gab sie ihm zur Furcht, und er fürchtete Mich und war zerknirscht vor Meinem Namen.',
        6: 'Das Gesetz der Wahrheit war in seinem Munde, und Verkehrtheit ward nicht gefunden auf seinen Lippen; in Frieden und Geradheit wandelte er mit Mir, und brachte viele von der Missetat zurück.',
        7: 'Denn die Lippen des Priesters sollen der Erkenntnis hüten, und das Gesetz sollen sie von seinem Munde suchen; denn ein Bote Jehovahs der Heerscharen ist er.',
        8: 'Ihr aber seid vom Weg abgewichen, habt viele im Gesetz straucheln lassen, ihr habt den Bund des Levi verdorben, spricht Jehovah der Heerscharen.',
        9: 'Und auch Ich habe euch verächtlich und niedrig gemacht allem Volk, gleichwie ihr Meine Wege nicht haltet und die Person anseht im Gesetz.',
        10: 'Haben wir alle nicht einen Vater? Hat nicht ein Gott uns geschaffen? Warum handeln wir treulos, der Mann an seinem Bruder, und entweihen unserer Väter Bund?',
        11: 'Treulos geworden ist Jehudah, Greuliches geschah in Israel und in Jerusalem, denn Jehudah hat entweiht die Heiligkeit Jehovahs; denn er liebte und vermählte sich mit der Tochter eines ausländischen Gottes.',
        12: 'Ausrotten wird Jehovah den Mann, der das tut, der wacht und antwortet aus Jakobs Zelten, und der dem Jehovah der Heerscharen Speiseopfer herzubringt.',
        13: 'Und dies tut ihr zum zweiten: ihr bedeckt mit Tränen den Altar Jehovahs, mit Weinen und Jammer, daß Er nicht mehr zu dem Speiseopfer Sich wendet und Wohlgefälliges annimmt aus eurer Hand.',
        14: 'Und ihr sprecht: Warum? Darum, daß Jehovah Zeuge ist zwischen dir und dem Weibe deiner Jugend, der du treulos bist geworden, und doch ist sie deine Gefährtin und deines Bundes Weib.',
        15: 'Und das tat nicht einer, und der Überrest, in dem der Geist war. Und was dann der eine, der Gottes Samen suchte? Darum hütet euch in eurem Geist, daß keiner dem Weibe seiner Jugend treulos wird.',
        16: 'Denn Er haßt das Entlassen, spricht Jehovah, der Gott Israels, und Gewalttat bedeckt seinen Anzug, spricht Jehovah der Heerscharen; darum hütet euch in eurem Geist, daß ihr nicht treulos handelt.',
        17: 'Ihr habt durch eure Worte ermüdet den Jehovah und ihr sprecht: Womit ermüdeten wir Ihn? Damit, daß ihr sagt: Jeder, der Böses tut, ist in Jehovahs Augen gut, und Er hat an ihnen Lust; oder: Wo ist der Gott des Gerichts?',
    },
    3: {
        1: 'Siehe, Ich sende Meinen Boten, und er räumt den Weg vor Meinem Angesicht, und plötzlich wird kommen in Seinen Tempel der Herr, Den ihr sucht, und der Bote des Bundes, an Dem ihr Lust habt; siehe, Er kommt, spricht Jehovah der Heerscharen.',
        2: 'Und wer hält aus den Tag Seines Kommens, und wer besteht bei Seinem Erscheinen? Denn wie des Goldschmieds Feuer ist Er, wie der Walker Lauge.',
        3: 'Und sitzen wird Er, schmelzend und reinigend das Silber, und wird reinigen die Söhne Levis und abtreiben sie wie Gold und wie Silber, und sie werden dem Jehovah herbeibringen Speiseopfer in Gerechtigkeit.',
        4: 'Und angenehm wird dann Jehovah sein das Speiseopfer Jehudahs und Jerusalems, wie in der Urzeit Tagen und in der Vorzeit Jahren.',
        5: 'Und nahen werde Ich euch zum Gericht, und Ich werde eilig Zeuge sein wider die Zauberer und die Ehebrecher und die zur Lüge schwören und erpressen den Lohn des Lohnarbeiters, die Witwe und die Waise und den Fremdling beugen und Mich nicht fürchten, spricht Jehovah der Heerscharen.',
        6: 'Denn Ich, Jehovah, ändere Mich nicht; darum seid ihr, Söhne Jakobs, nicht alle worden.',
        7: 'Seit eurer Väter Tagen seid ihr von Meinen Satzungen abgewichen und habt sie nicht gehalten. Kehrt zurück zu Mir, so will Ich wieder zu euch zurückkehren, spricht Jehovah der Heerscharen. Ihr aber sprecht: Worin sollen wir zurückkehren?',
        8: 'Berückt wohl ein Mensch Gott? daß ihr wollt Mich berücken und ihr sprecht: Worin berückten wir Dich? im Zehnten und im Hebeopfer.',
        9: 'Mit Verwünschung seid ihr verflucht, und ihr wollt Mich berücken, die ganze Völkerschaft?',
        10: 'Bringt herein alle den Zehnten in das Schatzhaus, auf daß Ausbeute sei in Meinem Hause, und prüft Mich doch damit, spricht Jehovah der Heerscharen, ob Ich euch nicht des Himmels Fenster öffne, und Segen für euch ausleere bis zum Überfluß.',
        11: 'Und Ich bedrohe für euch den Fresser, daß er des Bodens Frucht euch nicht verderbe, und euch nicht fehltrage der Weinstock auf dem Felde, spricht Jehovah der Heerscharen;',
        12: 'Und alle Völkerschaften werden euch selig preisen, denn ein Land der Lust sollt ihr sein, spricht Jehovah der Heerscharen.',
        13: 'Stark waren wider Mich eure Worte, spricht Jehovah, und ihr sprecht: Was haben wir wider Dich geredet?',
        14: 'Ihr sprachet: Eitel ist es, zu dienen Gott, und welcher Gewinn ist, daß wir Seine Verordnung halten und wir Leid tragend einhergehen vor dem Angesicht Jehovahs der Heerscharen?',
        15: 'Und nun preisen wir selig die Vermessenen. Sie wurden auch aufgebaut, die Ungerechtigkeit taten; auch versuchten sie Gott und entrannen.',
        16: 'Dann aber redeten miteinander die, so Jehovah fürchteten, ein Mann mit seinem Genossen, und Jehovah merkte auf und hörte, und es ward vor Seinem Angesicht geschrieben ein Gedenkbuch über die, so den Jehovah fürchten und an Seinen Namen denken.',
        17: 'Und sie sollen Mir, spricht Jehovah der Heerscharen, für den Tag, den Ich mache, ein Eigentum sein, und Ich will sie bemitleiden, wie ein Mann bemitleidet seinen Sohn, der ihm dient.',
        18: 'Und ihr werdet zurückkehren und sehen, wie es ist zwischen dem Gerechten und dem Ungerechten, zwischen dem, der Gott dient und dem, der Ihm nicht dient. Denn siehe, es kommt der Tag, der wie der Ofen brennt; und alle Vermessenen und die, so Ungerechtigkeit taten, sind Stoppel, und der Tag, der kommt, entflammt sie, spricht Jehovah der Heerscharen, und weder Wurzel, noch Ast wird er denselben hinterlassen. Euch aber, die ihr Meinen Namen fürchtet, wird aufgehen die Sonne der Gerechtigkeit, und Heilung unter ihren Flügeln, und ihr geht aus und wachset heran wie die Mastkälber. Und die Gottlosen werdet ihr daniedertreten; denn Asche sollen sie unter den Sohlen eurer Füße sein an dem Tage, den Ich mache, spricht Jehovah der Heerscharen. Gedenkt an das Gesetz des Moses, Meines Knechtes, das Ich ihm gebot auf Choreb an ganz Israel, an die Satzungen und Rechte. Siehe, Ich sende euch Elijah, den Propheten, bevor da kommt der Tag Jehovahs, der große und furchtbare. Und er wird das Herz der Väter zu den Söhnen zurückwenden, und das Herz der Söhne zu ihren Vätern, auf daß Ich nicht komme und schlage mit dem Banne das Land.',
    },
}
